mapper.select:
SELECT pep.id, pep.prescription_name, p.name as patient_name, p.gender, TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) as age, p.birth_date, p.medical_record_no as medical_record_number, p.disease_type, p.enrollment_institution, pep.execution_institution, pep.prescription_status, pep.prescribing_doctor, pep.created_time, pep.updated_time FROM patient_exercise_prescription pep LEFT JOIN patient p ON pep.patient_id = p.id
AND p.disease_type = #{query.diseaseType}
AND pep.prescription_status = #{query.prescriptionStatus}
AND p.enrollment_institution = #{query.enrollmentInstitution}
AND pep.execution_institution = #{query.executionInstitution}
AND pep.prescribing_doctor LIKE CONCAT('%', #{query.prescribingDoctor}, '%')
AND (p.name LIKE CONCAT('%', #{query.searchKeyword}, '%') OR p.medical_record_no LIKE CONCAT('%', #{query.searchKeyword}, '%'))
ORDER BY pep.created_time DESC
